export const INSCRIPCIONES_MIN = [{"id": "968A", "date": "finales del s. VI a.C.", "text": "α̣ἴτε ἄλλα[ι] <--\nἀλοιφᾶι (h)ορο͂ <--\nβέλτερον <--", "dialecto": "Acayo", "certeza": "d"}, {"id": "2821A", "date": "mediados del s. V a.C.", "text": "[- - - πὸτ τὸν δεῖνα συνθ]έμενος : ἒ̅ ποτ' ἄλ-\n[λον]", "dialecto": "Acayo", "certeza": "d"}, {"id": "2822A", "date": "segunda mitad del s. V a.C.", "text": "περὶ το͂ν Ι[- - -] \nτὰν Μελίζ[ουσαν - - -]- \nια εἴε̅", "dialecto": "Acayo", "certeza": "d"}, {"id": "2824B", "date": "mediados del s. V a.C.", "text": "[περὶ] εὐπρα[γ]ίας καὶ \n[ὑγιεί]ας αὐτο͂ καὶ γέ-\nν(ε)ος ποτ[ευχό]μ̣ενο[ς]", "dialecto": "Acayo", "certeza": "d"}, {"id": "4144A", "date": "primera mitad del s. V a.C.", "text": "[- - -]Ι[. . .]Σ : θε:ο̣ῖς : Ο[- - -] \n[- - -] τὰ[ν] θ̣έ̣ρμαν : καὶ [- - -]\n[- - -] ἐξ̣(ι)δρό̅σας", "dialecto": "Acayo", "certeza": "d"}, {"id": "109A", "date": "s. V a.C.", "text": "θεός• αἰ Ἀθ[- - -] \nἢ ἐπευχόμε[νος - - -]\nπαῦσαι τὸ ν[εῖκος - - -]\nκαλὰ • ἢ 'πὶ πάν[τα - - -]", "dialecto": "Acayo", "certeza": "n"}, {"id": "4145B", "date": "primera mitad del s. V a.C.", "text": "[θεό]ς· [Ἱ]πόζαμο(ς) ἐπισ̣[τορεῖται - - -]\n[- - -]Ε̣ΟΥΣΟ[. .]ΑΤΑ[. .][- - -] \n[- - - θύσας] ἒ̅ εὐξ̣άμενο[ς - - -] \n[- - -]ν ὅτι κά[λλι]στα Κ̣[.][- - -] \n[- - -]ΣΤΑΤΑ[. . . .]ΕΝΕ[. .][- - -] \n[- - -] ἱαρο͂τα[ι]", "dialecto": "Eleo", "certeza": "d"}, {"id": "LOD 29", "date": "ss. V-IV a.C.", "text": "῏Ε ἄλλαν μαστείε̅ι ;", "dialecto": "Eleo", "certeza": "d"}, {"id": "2493A", "date": "principios del s. IV a.C.", "text": "Ζεῦ καὶ Διώνα· ἦ ἔσσονται παῖ-\nδες ἐκ τᾶς γυναικὸς Κεβαλίωι \nτᾶς νῦν ἔχει κ[α]ὶ ζώσοντι;", "dialecto": "Macedonio", "certeza": "d"}, {"id": "94", "date": "primer cuarto del s. IV a.C.", "text": "Ἄλβειος περὶ παντυχίας", "dialecto": "Macedonio", "certeza": "n"}, {"id": "LOD 89Aa", "date": "s. IV a.C.", "text": "Τύχα ἀγαθά. Ἦ τυγχάνοιμί κα ἐμπορευόμενος \nὅπυς κα δοκῆι σύμφορον ἔμειν καὶ ἄγων τῆι (?) κα δοκῆι \nἅμα τᾶι τέχναι χρεύμενος.", "dialecto": "Rodio", "certeza": "d"}, {"id": "27A", "date": "principios del s. V a.C.", "text": "[- - -] αἰ συνναίεν ΤΑΑΡ[- - -]", "dialecto": "Textos no griegos", "certeza": "s"}];
// Texto de MINORITARIOS_1_Redaccion_v9: §3-§6.
export const APARTADOS_MIN = [{"sec": "§3.1", "name": "Macedonia y Dodona", "paras": ["De todas las regiones cuyos dialectos se examinan en este capítulo, Macedonia es la que mantuvo con el santuario una relación política más estrecha, aunque bastante tardía. El reino moloso, en cuyo territorio se encontraba Dodona desde finales del s. V a.C., quedó vinculado a la casa real macedonia a mediados del s. IV a.C.: la princesa molosa Olimpíade casó con Filipo II, su hermano Alejandro el Moloso se crio en la corte de Pela y recibió de Filipo la Casopia, con las ciudades que la tradición llamaba colonias eleas, y, tras la muerte de Alejandro en Italia en el 331 a.C., Olimpíade gobernó la Molosia como si fuera suya (cap. 12, §2). El episodio que mejor refleja esa dependencia afecta al propio santuario: cuando los atenienses, por orden del oráculo, adornaron la estatua de Dione y enviaron una teoría con un sacrificio costoso, Olimpíade les reprochó por carta que intervinieran en un santuario situado en una tierra que consideraba suya, y Hiperides tuvo que defender ante la asamblea la legitimidad de la ofrenda (Hyp. Eux. 24-26). La relación cambió de signo con Pirro, que expuso en el santuario los escudos tomados a los macedonios de Antígono Gónatas (Paus. 1.13.2-3), y volvió a estrecharse durante la guerra de los aliados (220-217 a.C.), cuando el Epiro, aliado de Filipo V, sufrió el saqueo etolio que arrasó Dodona en el 219 a.C. (Plb. 4.67.3).", "Esa cercanía política apenas tiene reflejo en las laminillas. Lhôte (2006: 429) observaba que los macedonios parecían ausentes de Dodona, y el corpus de 2013 solo ha añadido dos candidatos, ambos identificados por el antropónimo del consultante. La paradoja se explica, en buena medida, por la historia lingüística del reino. La administración macedonia empleó en la escritura, ya en el s. IV a.C., el ático y después la koiné, con exclusión casi completa del dialecto local, que solo conocemos por glosas, por la onomástica y por unos pocos textos privados (cap. 12, §2). Un macedonio que consultara el oráculo en el s. IV a.C. tenía, por tanto, muchas probabilidades de escribir en koiné o en un ático indistinguible de ella, y su consulta, si no declaraba su procedencia, se cuenta hoy entre las jónico-áticas."]}, {"sec": "§3.2", "name": "El dialecto macedonio", "paras": ["La investigación reciente coincide en que el macedonio era un dialecto griego próximo al dórico del Noroeste. Méndez Dosuna (2012: 145), en un juicio que hace suyo Hatzopoulos (2018: 321), lo define como un pariente cercano de esas variedades, del que solo lo separaban dos rasgos, la sonorización de las oclusivas sordas /p t k/ en [b d g] y la de las fricativas /f θ s x/ en [v ð z ɣ], y Crespo (2018: 329) lo considera un dialecto dórico del Noroeste que compartía isoglosas con el tesalio vecino. El rasgo más característico, la sonorización, que el propio Crespo (2018: 330) atribuye ahora a una evolución interna del dialecto y no a la influencia de otras lenguas de la zona, era ya percibido por los antiguos como seña de identidad de los macedonios. Herodiano explica el nombre de Berea por esa tendencia: Βέροια πόλις Μακεδονίας, ἣν Φέρωνα κτίσαι φασίν, αὐτοὺς δὲ τὸ φ εἰς β μεταποιεῖν, ὡς Φάλακρον Βάλακρον καὶ Βίλιππον καὶ Κεβαλῖνον (Hdn.Gr. 1.281). Fuera de los nombres propios, el principal texto dialectal es la defixio de Pela del s. IV a.C., cuyo griego, con ᾱ, -σσ-, -ντι y ζ de *dj y *gʷj, es muy semejante al del Noroeste, aunque no idéntico.", "Un texto escrito en macedonio no se distingue, por tanto, de uno noroccidental salvo por la sonorización, que en las consultas solo puede aflorar en los nombres propios o en alguna forma aislada, y por algún rasgo que lo separe del dórico, como los futuros que examina el apartado siguiente."]}, {"sec": "§3.3", "name": "Las consultas", "paras": ["La consulta más extensa es I.Dodone DVC 2493A (principios del s. IV a.C.):", "Ζεῦ καὶ Διώνα· ἦ ἔσσονται παῖδες ἐκ τᾶς γυναικὸς Κεβαλίωι τᾶς νῦν ἔχει κ[α]ὶ ζώσοντι;", "Méndez Dosuna (2007g: 283-284), que fue el primero en proponer su origen macedonio, la analizó por exclusión. El texto no es jónico-ático, porque conserva la ᾱ en Διώνα y en τᾶς, la -σσ- en ἔσσονται y la desinencia -ντι en ζώσοντι; tampoco es beocio, por la ζ de Ζεῦ y de ζώσοντι, por ἐκ ante consonante, por el dativo Κεβαλίωι y por las desinencias sin aspirada, donde el beocio tendría Δεῦ, ἐς, Κεβαλίοι o Κεβαλίυ, δώσονθι y ἔσσονθη, y no parece tesalio, porque Διώνα, Κεβαλίωι y ζώσοντι conservan la Ω, porque emplea ἐκ y no ἐς, y por el dativo en -ωι y las desinencias sin -νθ-. Ninguno de estos rasgos es, con todo, concluyente frente al tesalio, cuyas inscripciones admiten excepciones en todos ellos, como reconoce el propio autor. El dórico parecía excluido por los futuros: un consultante dorio habría escrito ἐσσέονται y ζωσέοντι, con el futuro dórico, y un futuro del tipo heracleota, con sinicesis y absorción de la yod, le parecía a Méndez Dosuna (2012: 144) muy improbable. En su estudio de las consultas no dóricas, sin embargo, el autor admite que esas formas pueden ser futuros dóricos “encubiertos”, ἐσσόνται y ζωσόντι, resultado de la simplificación de -εοντ- en -οντ- o de la sinicesis seguida de la formación y la absorción de una yod (Méndez Dosuna 2018a: 292). Con ello, el argumento lingüístico pierde fuerza, y la adscripción descansa sobre todo en el antropónimo.", "El nombre Κεβάλιος es un hápax, pero su formación es transparente: corresponde a un *Κεφάλιος, no documentado, derivado de κεφαλή, como el frecuente Κέφαλος o Κεφαλῖνος, y presenta la β por φ que los antiguos atribuían a los macedonios. El paralelo más cercano es el macedonio Κέβαλος que transmite el códice F de Diodoro (D.S. 19.44.1), y la misma raíz sonorizada aparece en Κεβαλῖνος y en el hipocorístico Κέββας, documentado en Macedonia y en Tesalia entre el s. III a.C. y el s. I d.C. Méndez Dosuna (2007g: 284; 2018a: 293) advierte que un antropónimo no basta para establecer el origen de un texto, porque los nombres se toman en préstamo con facilidad, pero subraya que los nombres macedonios solo se pusieron de moda a finales del s. IV a.C. y que, si la datación de los editores es correcta, un préstamo resulta poco probable a comienzos del s. IV a.C. En CIOD, donde la consulta se fecha hacia el 375-350 a.C., se llega a la misma conclusión y se propone que Κεβάλιος fuera un macedonio bien integrado en el Epiro, cuyo dialecto habría adoptado salvo en el nombre; la otra cara de la laminilla, I.Dodone DVC 2496B, lleva la inicial Κ, que se interpreta como la marca del consultante. Si la atribución se confirma, se trataría del primer testimonio del dialecto macedonio hallado fuera de Macedonia y del texto dialectal macedonio más extenso después de la defixio de Pela, como señalan Martín González y Paschidis (2017: 184).", "La segunda consulta, I.Dodone DVC 94 (primer cuarto del s. IV a.C.), solo conserva el nombre del consultante y el asunto: Ἄλβειος περὶ παντυχίας. El antropónimo es también un hápax. Curbera (2013), en el apéndice onomástico de la edición, lo interpretó como la forma macedonia de Ἀλφειός, nombre documentado en Tesalia y en otras regiones, y Méndez Dosuna (2018a: 293) le da la razón frente a la alternativa de un romano llamado Albius, improbable en una fecha tan alta; en CIOD se defiende la misma interpretación, con la observación de que el antropónimo debe acentuarse Ἄλφειος, a diferencia del hidrónimo Ἀλφειός. El texto no presenta ningún rasgo dialectal, de modo que la adscripción descansa por entero en el nombre, y se califica como tal.", "Los demás testimonios onomásticos no alcanzan para una adscripción. El mismo hipocorístico Κέββας forma por sí solo la inscripción I.Dodone DVC 480B (primera mitad del s. IV a.C.), que en CIOD se interpreta como la etiqueta de una consulta borrada en la otra cara. El nombre se documenta en siete inscripciones, cinco de Tesalia, una de Iliria y una de Macedonia, y en CIOD se explica como un diminutivo con geminación de un *Κέφφας, con la β por φ que comparten el macedonio y el ilirio, sin que nada permita decidir entre ambos orígenes. La inscripción queda, por ello, sin clasificar, y tampoco basta el nombre Βάλλα de la mezcla dialectal de I.Dodone DVC 2674B (principios del s. IV a.C.), que Curbera relaciona con la raíz de φαλός y φαλιός.", "Dos consultas, como máximo, y ambas de la primera mitad del s. IV a.C., son todo lo que el corpus permite atribuir a hablantes de macedonio, y en las dos el indicio decisivo es el nombre. La cifra no contradice la estrecha relación de Macedonia con el santuario, que se intensificó justo cuando el macedonio dejaba de escribirse: los macedonios que acudieran a Dodona en la segunda mitad del s. IV a.C. escribirían, con toda probabilidad, en koiné, y sus consultas no pueden distinguirse de las de otros hablantes de esa variedad (cap. 12). La política macedonia se refleja, en cambio, en el contenido de alguna consulta ajena al dialecto, como la del tesalio de Histiótide que pregunta por la ἐπιβουλὰν Φιλίπ[που] en I.Dodone DVC 191A (mediados del s. IV a.C.), que Lhôte (2017b: 44) fecha entre el 356 y el 353 a.C., en el contexto de la intervención de Filipo II en Tesalia."]}, {"sec": "§4", "name": "Los dialectos del Peloponeso", "paras": ["El Peloponeso es la región cuya relación con Dodona resulta más difícil de valorar. Lhôte (2006: 429) lo excluía del área de influencia del oráculo, porque Delfos y Olimpia atendían las necesidades de sus habitantes, y la observación sigue siendo válida en términos generales: ninguna consulta pública procede de una comunidad peloponesia, y los topónimos peloponesios, como Olimpia o Nemea, pueden designar el destino de un epirota que acude a los juegos y no la patria del consultante (cap. 4, §2). Las fuentes literarias y la arqueología documentan, sin embargo, relaciones antiguas del santuario con Esparta y con la Élide, y las colonias aqueas de la Magna Grecia frecuentaron el oráculo desde finales del s. VI a.C. Los dialectos peloponesios de rasgos más marcados, el eleo, el acayo y el laconio, se examinan aquí; las variedades dóricas de la Argólide, de Corinto y de Mesenia, que comparten con el dórico del entorno el vocalismo de la Doris mitior o no se distinguen de él en textos breves, se estudian en el dórico general (cap. 4), y el arcadio no se documenta en el corpus."]}, {"sec": "§4.1.1", "name": "La Élide y Dodona", "paras": ["La relación entre Dodona y la Élide se ha planteado sobre todo a través de Olimpia, el otro gran santuario de Zeus del Occidente griego. Desde finales del s. VIII a.C., los dos santuarios recibieron ofrendas de tipos muy semejantes, como las figurillas de Zeus guerrero y de Zeus Keraunios, fíbulas casi idénticas y trípodes con asas en forma de caballo, y en Dodona se ha hallado un casco de hacia el 600 a.C. con la inscripción ΟΛΥΜΠ, mientras que un papiro de Oxirrinco afirma que en Dodona Zeus no era Naios, sino Olímpico. Chapinal-Heras (2021: 132-133) explica esas coincidencias por la condición de santuarios de Zeus de ambos lugares y no por una relación de dependencia, y recuerda que Trasibulo de Elis, de la estirpe adivina de los Iámidas, erigió en Olimpia una estatua de Pirro.", "La tradición sitúa, además, una presencia elea en el propio Epiro. El testimonio principal es un pasaje del discurso Sobre el Haloneso, que acusa a Filipo II de haber arrasado τὰς δ’ ἐν Κασσωπίᾳ τρεῖς πόλεις, Πανδοσίαν καὶ Βούχεταν καὶ Ἐλάτειαν, Ἠλείων ἀποικίας ([D.] 7.32), mientras que Teopompo nombra esas ciudades, junto a Bitia, como ciudades de los casopeos, sin aludir a su origen (Theopomp.Hist. FGrHist 115 F 206). A partir de ese pasaje, Hammond y Dakaris dataron la fundación de las colonias entre los ss. VIII y VI a.C. y les atribuyeron un papel decisivo en el control de la Casopia y en la difusión del culto de Zeus, y la mayor parte de la bibliografía ha aceptado su existencia. Lhôte considera Pandosia, Bucheta y Elatria colonias eleas fundadas hacia el 700 a.C. y atribuye a los colonos los nombres de Pandosia y de Elatria; Cabanes ve en Pandosia, en la lista de teorodocos de Epidauro de hacia el 360 a.C., la representante de las colonias eleas fundadas al sur de la Tesprotia, y Filos supone en la costa epirota un cierto bidialectalismo temprano, debido a las colonias corintias y eleas. Domínguez Monedero (2015: 123-124) sostiene, sin embargo, que la arqueología no ofrece ningún indicio de ocupación colonial ni de entidades urbanas en esos lugares antes de mediados del s. IV a.C., y el mismo autor (Domínguez Monedero 2017: 86-87) interpreta la tradición de un origen eleo como una construcción identitaria de los propios casopeos, que en época helenística se apropiaron del héroe fundador eleo Óxilo. La cuestión sigue abierta y tiene consecuencias para las laminillas, porque las colonias eleas del Epiro se han invocado para explicar el alfabeto y los rasgos de algunas consultas atribuidas a la Élide (§4.1.3).", "La Élide aparece, por último, en el bando contrario al santuario en la guerra de los aliados, cuando su alianza con la Liga Etolia la situó frente a Filipo V y a los epirotas en los años del saqueo de Dodona (§3.1). Nada de ello tiene reflejo en las consultas, que son en su inmensa mayoría anteriores a esa fecha."]}, {"sec": "§4.1.2", "name": "El dialecto eleo", "paras": ["El eleo es uno de los dialectos griegos de rasgos más marcados, y Lhôte (2006: 430) ponía como ejemplo de un texto reconocible a primera vista una forma como πολιτειομένοιρ. La vocal larga /ɛː/ era tan abierta que se escribía a menudo con α, como en μά por μή, ϝράτρα por ῥήτρα o ἔα por εἴη; la secuencia ερ pasó a αρ en φάρεν, ϝάργον o πάρ, la forma apocopada de περί; el dialecto era psilótico y no notaba la aspiración, y la sigma final se convirtió en ρ, de manera regular en las inscripciones más recientes y en alternancia con -ς en las antiguas. Comparte además con los dialectos de la Doris severior la notación con Η y Ω de las vocales medias largas secundarias (cap. 6). Más discutido es el uso de ζ por δ en tres de las inscripciones eleas más antiguas, como ζέ, ζέκα o ζίκαια, que Méndez Dosuna (1993a: 83-85, 102) interpreta como prueba de una pronunciación fricativa de /d/ y que no tiene continuidad en los textos posteriores, escritos con δ; el mismo dialecto representa con δδ el resultado de *dj, como el beocio, el laconio y el cretense. Los verbos en -εύω, por último, forman en eleo un presente en -είω, como φυγαδείην o λατρειόμενον.", "El alfabeto de la Élide era del tipo “rojo”, con gamma lunada, qoppa y sigma de tres trazos; se distinguía del arcadio solo por la sigma y del laconio por la gamma y la qoppa, y tenía poco en común con el aqueo. Como se verá, esos mismos rasgos se encuentran en el alfabeto que Lhôte considera propio de Dodona, y esa coincidencia es el origen de buena parte de las dudas que plantean las consultas del corpus atribuidas a la Élide."]}, {"sec": "§4.1.3", "name": "Las consultas en alfabeto de la Élide", "paras": ["Los editores de I.Dodone DVC atribuyen al alfabeto de la Élide seis consultas que conservan, además, un rasgo no jónico-ático visible. Son I.Dodone DVC 382A (s. IV a.C.), Ἐπεύκτο̄ι περ' ὑγι<εί>ας; 1993A (finales del s. VI a.C.), hο̄́ς κα νικο͂μες Δαμόδ[οκος - - -] Φιλόϝοινος, Καρίο̄ν ὄκα [- - -]; 2357B (principios del s. V a.C.), τᾶς δο̄ρ̣εᾶς τᾶς ἐν Ἐλέαι̣; 2374A (primera mitad del s. V a.C.), [- - -]σστου : τύχα̣ς [- - - πε]ρὶ γενεᾶς : Κλεμάχ[ου - - -]; 2670B (principios del s. V a.C.), con [- - -] τὰν ὕλαν en su última línea, y 2830B (primera mitad del s. V a.C.), [- - -]εινις γενεὰ[ν - - -] τύχα. Ninguno de esos rasgos es eleo. La ᾱ de τᾶς, τύχας, τάν o τύχα es común a todos los dialectos distintos del jónico-ático; κα y la desinencia -μες de νικο͂μες excluyen el eolio, pero no ningún dialecto dórico, y el περ' elidido de 382A, si no es la apócope πέρ, solo excluye el ático. En las seis, por tanto, la adscripción al eleo depende por entero de la identificación del alfabeto, que el criterio de la introducción admite como base de una adscripción dudosa siempre que esté bien identificado (§3.2.5).", "Esa identificación no es firme. La bibliografía atribuye a la Élide un total de once inscripciones, casi todas por indicación de los editores de I.Dodone DVC, entre ellas I.Dodone DVC 27A, que se cuenta entre los textos no griegos (§5.2), y 307A (segunda mitad del s. V a.C.), cuya autopsia ha confirmado un alfabeto tesalio (cap. 7). Lhôte (2006: 333-334) definió como alfabeto local de Dodona un alfabeto “rojo”, de tipo eubeo, con alfa en forma de F inclinada, delta en forma de D, iota recta y rho con el trazo derecho casi horizontal, y en CIOD se atribuyen a ese alfabeto dos de las seis consultas, I.Dodone DVC 382A, que se data hacia el 425-400 a.C., y 2357B, del mismo período, así como las líneas finales de 2670B. Johnston (2021: 111-113) ha mostrado, por su parte, que ninguna laminilla presenta todas las letras del alfabeto de Lhôte y que la variedad de las formas en el corpus aconseja hablar de una escritura fluida más que de alfabetos de ciudad bien delimitados. Con letras compartidas por varios alfabetos “rojos” y en textos de pocas palabras, la diferencia entre un alfabeto de la Élide y uno de Dodona puede depender de un solo trazo.", "El examen individual de las consultas refuerza la duda. En I.Dodone DVC 382A, el antropónimo Ἔπευκτος solo se documenta en Acaya, y la secuencia ΠΕΡΥΓΙΑΣ, que los editores leen περ' ὑγι<εί>ας, se lee en CIOD πὲρ ὑγίας, con la apócope y con la forma ὑγίας, que en el corpus se documenta desde mediados del s. V a.C.; ninguna de las dos lecturas es elea, porque la forma apocopada de περί en este dialecto es πάρ. En I.Dodone DVC 2357B, la Ἐλέα en la que el consultante hizo su donación no es la Élide, sino la ciudad tesprota de ese nombre, que vuelve a aparecer en la consulta de Sátiro sobre un esquifo que no se consagró ἐν Ἐλέαι, I.Dodone Lhôte 113 (ss. IV-III a.C.). En CIOD se interpreta la consulta como una queja ante el oráculo por una donación hecha a un santuario de Elea, aunque δωρεά podría designar también la recompensa recibida por el consultante, como en I.Dodone DVC 3517A (segunda mitad del s. IV a.C.) y 3663B (primera mitad del s. IV a.C.); en cualquier caso, la consulta remite a la Tesprotia, a cuyo territorio perteneció Dodona hasta finales del s. V a.C., y no a la Élide. I.Dodone DVC 2670B, por su parte, no es una sola inscripción. Lhôte, en CIOD, sostiene que basta observar el facsímil para comprobar que los editores se equivocan al tratarla como un único texto y distingue en la cara B, además de una gran gamma que pertenece a la inscripción de la otra cara, cuatro textos superpuestos, que ordena de este modo: las dos primeras líneas de 2670B, en alfabeto beocio, de hacia el 450-440 a.C., con los nombres de dos consultantes, quizá un megarense y un beocio; 2669B, de hacia el 430 a.C.; las dos últimas líneas de 2670B, en el alfabeto local de Dodona, de hacia el 430-425 a.C., que contienen τὰν ὕλαν y que interpreta como una pregunta sobre la licitud de tomar madera junto a un río, y 2671B, de hacia el 425 a.C., grabada encima de las anteriores. La propuesta, que evita suponer las dos omisiones de la ρ que exige la lectura de los editores, solo podrá confirmarse mediante autopsia, pero basta para separar el rasgo no jónico-ático de las últimas líneas de la escritura de las primeras. I.Dodone DVC 2374A y 2830B, por último, se atribuyen a la Élide con reservas: la primera, a la Élide o a Siracusa y sus colonias, y la segunda, a una colonia elea, que, si se acepta la tradición de las colonias de la Casopia (§4.1.1), habría que buscar en el propio Epiro.", "Por estas razones, ninguna de las seis consultas se cuenta en esta tesis entre las eleas. Cinco se cuentan entre las no jónico-áticas: I.Dodone DVC 382A, 2357B y 2670B, cuyo alfabeto se asigna en CIOD al local de Dodona, y 2830B, como seguras, porque el περ' de 382A, ante un sustantivo legible, cumple el criterio de la introducción (§3.2.4.5) y la ᾱ de τᾶς, τὰν ὕλαν y τύχα excluye el jónico-ático, y 2374A, como dudosa, porque la alfa de τύχα̣ς no se lee con seguridad. La sexta, 1993A, se cuenta en el dórico general, por las razones que se exponen a continuación. En ninguna basta el alfabeto para la adscripción: en tres, la atribución a la Élide se enfrenta a la del alfabeto local; en otras dos, los propios editores la proponen como una posibilidad entre otras o la relacionan con una colonia elea, y en 1993A el texto contradice el dialecto que el alfabeto le asigna. La diferencia con las consultas aqueas, que se cuentan en el grupo con el mismo criterio (§4.2), reside en la naturaleza de cada alfabeto, porque el aqueo se reconoce por letras propias, como la san y la iota de tres trazos, mientras que las del alfabeto de la Élide son comunes a otros alfabetos “rojos” y, en particular, al que Lhôte atribuye a Dodona (§4.1.2). Las seis consultas conservan, con todo, su interés para la historia del santuario. Si el alfabeto de 2830B es, como proponen los editores, el de una colonia elea, y si esas colonias existían ya en la primera mitad del s. V a.C., la consulta procedería con toda probabilidad de los asentamientos de la Casopia, en el sur del Epiro, y sería, con 1993A, uno de los pocos rastros de sus habitantes en las laminillas; el hecho de que ninguna de las dos conserve un rasgo eleo indicaría, en ese caso, que esos colonos escribían ya en el dórico de su entorno y que solo el alfabeto delataba su origen. Con el alfabeto de la Élide o el de Siracusa, 2374A sería, por su parte, la consulta de un griego del Peloponeso o de Sicilia. La donación de 2357B, hecha en la Elea tesprota, documenta las relaciones del santuario con la Tesprotia en la época en que Dodona pertenecía todavía a ese territorio, y los textos superpuestos de 2670B muestran que una misma laminilla podía servir a consultantes de procedencia distinta, quizá un beocio y un consultante que escribía en el alfabeto local.", "El caso de I.Dodone DVC 1993A muestra mejor que ningún otro los límites de estas atribuciones. Es la consulta de un grupo de consultantes que preguntan, en primera persona del plural, cómo vencer, y cuyos nombres, Δαμόδ[οκος], Φιλόϝοινος y Καρίο̄ν, conservan la digamma intervocálica. La etiqueta de la otra cara, ἆθλα, y el contexto llevan a interpretar la consulta como la de unos atletas que aspiran a la victoria, quizá en Olimpia, aunque Chaniotis ha propuesto que se trate de un litigio. El texto, en cambio, contradice el eleo en un punto decisivo: escribe la aspiración en hο̄́ς, en un dialecto psilótico que no notaba el espíritu áspero. En CIOD, donde se fecha hacia el 475-450 a.C. y se atribuye a un “alfabeto eleo colonial”, se recuerda que la aspiración se nota en dos inscripciones eleas, procedentes del extremo sur de la Trifilia, que Minon atribuye a la influencia del laconio o del arcadio, y se propone que el rasgo se deba a las colonias eleas del Epiro, influidas por el habla epirota de su entorno. Esa explicación depende de unas colonias cuya existencia en el s. V a.C. se discute (§4.1.1) y, aun si se acepta, no convierte en eleo un texto que no conserva ningún rasgo de este dialecto. Con la aspiración, el κα y la -μες, la consulta es dórica, y se cuenta como segura en el dórico general (cap. 4), porque κα y -μες excluyen el eolio y el jónico-ático; su relación con la Élide descansa solo en la escritura y en la posible relación de la consulta con los juegos.", "El problema no se limita a esta consulta. La atribución de un alfabeto a una región, que en una inscripción breve depende a menudo de una o dos letras, ha llevado a contar como eleas consultas que no tienen nada de eleo, y lo mismo ocurre con otros alfabetos epicóricos del corpus. De las once inscripciones que los editores de I.Dodone DVC atribuyen al alfabeto de Eubea, Johnston (2021: 113) no encuentra un argumento firme en ninguna, y al menos tres están en dialecto dórico; la autopsia ha mostrado que I.Dodone DVC 307A, atribuida a la Élide, está escrita en alfabeto tesalio, y la propia noción de un alfabeto local de Dodona, al que CIOD asigna varias de estas consultas, se ha puesto en duda (Johnston 2021: 111-113). El alfabeto informa sobre la tradición de escritura de quien grabó la laminilla, que no siempre coincide con su dialecto ni con su procedencia, y por eso en esta tesis solo se tiene en cuenta como apoyo de un rasgo visible compatible con él (§3.2.5)."]}, {"sec": "§4.1.4", "name": "Otras formas atribuidas al eleo", "paras": ["Las dos consultas que se cuentan como eleas lo hacen por una forma aislada. I.Dodone Lhôte 29 (ss. V-IV a.C.) contiene la pregunta ῏Ε ἄλλαν μαστείε̄ι ;, con la variante en -είω del verbo μαστεύω, “buscar”, que el corpus emplea para la búsqueda de una nueva esposa, como en Ἦ ἄλλαν μαστεύων; de I.Dodone Lhôte 30 (= I.Dodone DVC 1, primera mitad del s. IV a.C.) o en ἐ͂ ἄλλαν μαστεύο̄; de I.Dodone DVC 2322A (mediados del s. V a.C.). Buck (1955: §161.1) ya citaba esta forma de Dodona junto a las eleas, y Lhôte (2006: 382-383) observa que la formación solo tiene paralelos en eleo, donde alterna con la forma en -εύω; la interpreta, sin embargo, como el resultado fonético regular de *-ēwyō, frente a -εύω, rehecho sobre el aoristo y el futuro, y concluye que μαστείε̄ι es un “notable arcaísmo dórico”, apoyándose en que el texto de la laminilla es más antiguo que los que presentan -εύω. Ese argumento ha perdido fuerza con el corpus de 2013, en el que μαστεύο̄ se documenta ya a mediados del s. V a.C. La forma admite, con todo, una explicación que no obliga a suponer un consultante eleo, y la adscripción se califica como dudosa.", "La segunda es I.Dodone DVC 4145B (primera mitad del s. V a.C.), una consulta muy fragmentaria cuyo consultante se llama [Ἱ]πόζαμο<ς>, con ζ en lugar de δ. Méndez Dosuna (2018b: 42) la relaciona con la ζ por δ del eleo arcaico, y la fecha encaja con la de las inscripciones eleas que presentan esa grafía, de entre el 600 y el 450 a.C. Dos datos aconsejan, sin embargo, prudencia. La grafía no es exclusiva del eleo, puesto que aparece en el rodio τόζ’ por τόδε y en el argivo ϝισζείε por εἰδείη, y en CIOD se interpreta como una pronunciación popular, documentada de forma esporádica en varios dialectos. El alfabeto, además, no es el de la Élide, sino el aqueo, con san, iota de tres trazos y delta redondeada, y es el mismo de I.Dodone DVC 4144A, grabada en la otra cara de la misma laminilla, quizá por la misma mano. El vocalismo de ἱαρο͂τα[ι], con ἱαρ-, es el regular del aqueo colonial, y la ausencia de aspiración que se ha supuesto en el antropónimo, si fuera segura, sería compatible con la psilosis elea, pero depende de una restitución. La combinación de una grafía que puede ser elea con un alfabeto aqueo no tiene, por ahora, una explicación segura. Ninguna fuente documenta una colonia elea en Acaya, pero las dos regiones eran vecinas, y Jeffery (1990: 224) explica el propio alfabeto aqueo como el resultado de la fusión de las escrituras de Sición y de Corinto, al este, con la de la Élide, al oeste, y la de la Fócide, al otro lado del golfo. En Olimpia, además, se han hallado dedicatorias en alfabeto aqueo que pueden proceder tanto de Acaya como de sus colonias de la Magna Grecia, cuyo alfabeto dejó también su huella a lo largo de la ruta que llevaba a Italia a través de las islas jonias. Un consultante de la Acaya occidental, en la frontera con la Élide, o de una colonia aquea en contacto con Olimpia pudo escribir, por tanto, en alfabeto aqueo un nombre con una grafía elea, y la ζ por δ sería entonces el único rastro del dialecto, aunque tampoco puede descartarse una grafía esporádica de un consultante aqueo. Como es la única consulta del corpus que conserva un rasgo que puede ser eleo, se mantiene entre las eleas, con la calificación de dudosa.", "Otras formas del corpus se han puesto en relación con el eleo sin que basten para la adscripción. El infinitivo ἐλπίδ(δ)ην de I.Dodone DVC 3022A (segunda mitad del s. IV a.C.), con δδ por ζ, podría ser eleo, pero el resultado δδ es también beocio, laconio y cretense, y la consulta es demasiado breve para precisar su dialecto; se cuenta entre las mezclas por la combinación con τῆς δίκα<ς>. La β por ϝ de βοικίαν en I.Dodone DVC 1575B (principios del s. IV a.C.) y de βοικόπεδον y βοικίαν en 2782A (ss. V-IV a.C.) aparece en el eleo βοικίαρ, pero también en laconio, en cretense, en argivo y en corcireo. La negación μα, que en eleo sería la forma de μή con ᾱ, se explica mejor como un rasgo del tesalio de Histiótide (cap. 7), según Méndez Dosuna (2018b: 42 n. 100), y el paso de -άω a -έω de ἡβέο̄ν, en I.Dodone DVC 3798 (s. IV a.C.), es común al eleo, al délfico, al etolio, al rodio y al cretense. En el corpus no se documenta, en cambio, ninguna de las formas que permitirían reconocer un texto eleo: ni la ᾱ por η, salvo la discutida negación μα, ni el rotacismo de la sigma final, ni la apócope πάρ.", "La conclusión de Méndez Dosuna (2018a: 287 n. 57) sigue, por tanto, en pie: ningún texto de Dodona presenta rasgos eleos inequívocos. Las dos consultas que aquí se cuentan como eleas descansan en una forma aislada que admite otra explicación, y las seis que los editores atribuyen al alfabeto de la Élide se cuentan entre las no jónico-áticas o en el dórico general, porque no conservan ningún rasgo eleo. Su número es, por tanto, el de las inscripciones que pueden relacionarse con la Élide, no el de los consultantes eleos demostrables."]}, {"sec": "§4.2", "name": "El acayo", "paras": ["La presencia aquea en el corpus está ligada, sobre todo, a las colonias de Acaya en la Magna Grecia. Las consultas mencionan Crotona, como la de I.Dodone DVC 24A (finales del s. V a.C.), sobre el traslado a esa ciudad, y la de 319 (mediados del s. V a.C.), [- - - Κ]ρ̣ότο̄νι, en cuya tau inclinada reconoce Johnston (2021: 114) la escritura aquea de Caulonia; el metapontino Arquias firma I.Dodone DVC 2333B (segunda mitad del s. IV a.C.), y I.Dodone Lhôte 148 (primer cuarto del s. V a.C.), Διονυσίο̄, está escrita en el alfabeto aqueo de la Magna Grecia. Esas consultas se integran en la red de relaciones del santuario con la Magna Grecia y Sicilia, a las que se llegaba por la ruta marítima del mar Jónico. El alfabeto aqueo se empleaba también en Ítaca y en Cefalenia, en la ruta del golfo de Corinto hacia el Epiro.", "El dialecto de Acaya es uno de los peor documentados del griego. Las inscripciones de la metrópoli presentan, desde finales del s. IV a.C., el vocalismo de la Doris mitior, mientras que las escasas inscripciones de las colonias tienen el de la Doris severior, y el adjetivo ἱαρός, regular en las colonias, alterna en el Peloponeso con formas en ἱερ- que proceden, con toda probabilidad, del arcadio. En textos breves como las consultas, el acayo no se distingue de los demás dialectos dóricos, y el único criterio disponible es el alfabeto, caracterizado por la iota de tres trazos, la san y la delta redondeada, con gamma lunada en la metrópoli y recta, en forma de I, en las colonias.", "Cinco consultas del capítulo se cuentan como aqueas por ese alfabeto y por un rasgo no jónico-ático visible, todas con la calificación de dudosas. La más antigua es I.Dodone DVC 968A (finales del s. VI a.C.), α̣ἴτε ἄλλα[ι] ἀλοιφᾶι <h>ορο͂ βέλτερον, escrita de derecha a izquierda en el alfabeto aqueo de la Magna Grecia, que conserva la ᾱ de ἀλοιφᾶι y es una de las consultas legibles más antiguas del corpus; Chaniotis la interpreta como una pregunta sobre el ungüento más conveniente para la vista. Tres pertenecen a una misma laminilla, que contiene una serie de textos en ese alfabeto, I.Dodone DVC 2821A-2824B, atribuidos por Johnston (2021: 114) a consultantes aqueos: 2821A (mediados del s. V a.C.), con la forma apocopada ποτ'; 2822A (segunda mitad del s. V a.C.), con la ᾱ de τάν, y 2824B (mediados del s. V a.C.), [περὶ] εὐπρα[γ]ίας καὶ [ὑγιεί]ας αὐτο͂ καὶ γέν<ε>ος ποτ[ευχό]μ̣ενο[ς], escrita con la gamma recta de las colonias, que conserva el preverbio dórico ποτ-; el genitivo αὐτο͂, con Ο, no permite decidir entre el vocalismo mitior y el severior. La quinta, I.Dodone DVC 4144A (primera mitad del s. V a.C.), con san, iota de tres trazos y delta redondeada, solo conserva [- - -] θε:ο̣ῖς [- - -] τὰ[ν] θ̣έ̣ρμαν : καὶ [- - -] ἐξ̣<ι>δρο̄́σας, con la ᾱ de τάν; en CIOD se interpreta como una consulta sobre la fiebre y su curación mediante la sudoración, y se propone que la escribiera, como 4145B en la otra cara, un peregrino de una colonia aquea. En ninguna de las cinco permite el texto decidir entre el acayo y otro dialecto dórico, y por eso la adscripción, que descansa en el alfabeto, se califica como dudosa. A ellas se suma I.Dodone DVC 109A (s. V a.C.), que no conserva ningún rasgo dialectal visible y se cuenta como aquea solo por el alfabeto. Los editores de I.Dodone DVC leen θεός· αἰ Ἀθ[- - -], con la conjunción αἰ, pero Johnston (2021: 113-114 y n. 15) entiende que la supuesta iota es una gamma de trazo recto y lee θεός· ἀγαθ[- - -], el comienzo de la invocación; la iota de tres trazos del resto del texto apunta, según él, a un consultante aqueo, probablemente de las colonias. La convivencia de ese alfabeto con la Η jónica obliga, con todo, a tomar la atribución con reservas.", "Las demás consultas en alfabeto aqueo no se cuentan en el capítulo. I.Dodone DVC 2823B (mediados del s. V a.C.), la única inscripción del corpus que reúne san, iota de tres trazos, gamma recta y delta redondeada, no conserva ningún rasgo dialectal visible, y queda sin clasificar, como I.Dodone DVC 491A (principios del s. V a.C.), hιεροῖ hάρμα, cuyo alfabeto es aqueo pero cuyo vocalismo ἱερ- no es el que cabe esperar en ese dialecto.", "Las consultas aqueas, todas en el alfabeto de las colonias y todas de los ss. VI y V a.C., documentan una presencia temprana de los griegos de la Magna Grecia en el santuario, a la que se suman las menciones de Crotona y de Metaponto. Su escaso número depende, como en el eleo, de la escritura: desaparecido el alfabeto epicórico, nada distingue la consulta de un aqueo de la de cualquier otro dorio."]}, {"sec": "§4.3", "name": "El laconio", "paras": ["Ningún dialecto peloponesio cuenta con una tradición tan rica sobre sus relaciones con Dodona como el laconio, y ninguno deja tan poca huella en las laminillas. Piccinini (2017: 87-99) ha reunido los testimonios de una devoción espartana que se remonta a la segunda mitad del s. VI a.C. Los grandes calderos de bronce con guerreros en el borde y figuras de banquetes, del mismo tipo que los que los espartanos dedicaban en Olimpia y en Samos, son, después de las corintias, las ofrendas más numerosas del s. VI a.C. en el santuario, y una sítula del s. V a.C. con la imagen de Zeus Amón, otro oráculo predilecto de los espartanos, prolonga esa relación. Las fuentes literarias sitúan a Dodona entre los oráculos que consultaban los espartanos en los asuntos graves: Lisandro intentó sobornar a las sacerdotisas para que apoyaran su reforma de la monarquía, las sacerdotisas predijeron a los lacedemonios la “batalla sin lágrimas” del 368 a.C. y, antes de Leuctra, el mono del rey de los molosos desordenó las suertes y la sacerdotisa advirtió a los espartanos que pensaran en su salvación y no en la victoria.", "En las laminillas, la presencia de laconios y mesenios solo puede deducirse de la onomástica y de los topónimos. Βρ[α]σίδας ἐπερωτῆ Δί[α καὶ Δι]ώναν, en I.Dodone DVC 3310B (mediados del s. IV a.C.), lleva el nombre del general espartano de la guerra arquidámica, y el verbo de la consulta, ἐνδατίσαι, solo encuentra paralelo, si se corrige en ἐνδιαιτῆσαι, en una inscripción de Esparta; I.Dodone DVC 4113B (s. IV a.C.) conserva el nombre Λ̣άκω[ν], y las consultas sobre la residencia en Selasia, en 2416A (s. IV a.C.), y en Turia, en 2554B (mediados del s. IV a.C.), apuntan a Laconia y a Mesenia. Ninguna de esas consultas conserva un rasgo laconio: I.Dodone DVC 3310B solo presenta la contracción ἐπερωτῆ y la ᾱ de Διώναν, comunes a todo el dórico, y se cuenta entre las no jónico-áticas.", "Los rasgos que permitirían reconocer un texto laconio son, además, de aparición tardía o poco frecuentes en textos breves. La σ por θ, como en σιός por θεός, el rotacismo de la sigma final y la β por ϝ se generalizan en las inscripciones laconias a partir del s. IV a.C., y el vocalismo de la Doris severior lo comparte el laconio con el eleo, el cretense, Cirene y las colonias de Tarento (cap. 6). Las propuestas laconias que se han hecho para algunas consultas no se sostienen. Los editores leyeron en I.Dodone DVC 3018A (ss. V-IV a.C.) πὲρ κο̄ματο͂ν, con el término que, según Aristóteles, los dorios usaban por δῆμοι (Arist. Po. 1448a35-38), pero el genitivo plural en -ων es imposible en dórico, y se trata del κῶμα de los tratados hipocráticos, el letargo o la epilepsia; la apócope πέρ, además, no es laconia. El ταγᾶς de I.Dodone DVC 3150A (s. IV a.C.), que Aristófanes pone en boca de la espartana Lampito (Ar. Lys. 105), designa también un cargo de las instituciones tesalias, y la consulta, que lo combina con la apócope πέρ, se cuenta en el tesalio (cap. 7). La β por ϝ de I.Dodone DVC 1575B y 2782A, que Méndez Dosuna (2018b: 40) relaciona con la cronología de esa grafía en Laconia, hacia el 400 a.C., es también elea, cretense, argiva y corcirea (§4.1.4). Más sugerente es el adverbio σάτει de I.Dodone DVC 228B (principios del s. IV a.C.), que Méndez Dosuna (2007g: 281) relaciona con el tsaconio σάτζι, “este año”, heredero del laconio; la consulta, que menciona un viaje por mar a Faros, se cuenta en el dórico general (cap. 4).", "La ausencia del laconio en las laminillas no significa que los espartanos no consultaran el oráculo, sino que no lo hacían, o no podemos reconocerlo, por escrito. Piccinini (2017: 97) atribuye la escasez de testimonios epigráficos al uso limitado de la escritura en Laconia para fines privados, y las consultas de Estado que transmiten las fuentes se hacían por medio de embajadores y, en el caso de Leuctra, mediante el sorteo, sin que haya razón para suponer que quedara de ellas una laminilla. La presencia laconia más visible en el santuario es, en definitiva, la de sus bronces y la de su colonia de Tarento, cuyo vocalismo severior se documenta en las consultas de la Magna Grecia (cap. 6)."]}, {"sec": "§5.1", "name": "El rodio", "paras": ["Las variedades dóricas del Egeo se han dado por ausentes del corpus, pero dos consultas presentan formas que se han relacionado con el rodio. El vínculo de Rodas con Dodona pasa, sobre todo, por sus colonias de Sicilia, Gela y Acragante, y lo documenta en el propio santuario el decreto por el que los molosos concedieron la proxenia a los ciudadanos de Acragante tras la embajada de tres de ellos, grabado en una placa de bronce del s. IV o del s. III a.C. que escribe ἔδοξε τοῖς Μολοσσοῖς προξενία[ν] δόμειν τοῖς Ἀκραγαντίνοις, con el infinitivo en -μειν característico del rodio. Giannakis (2024b: 126) ve en la consulta rodia de I.Dodone Lhôte 89Aa, si la interpretación de Lhôte es correcta, uno de los pocos testimonios de que el prestigio del oráculo llegaba a las islas del Egeo, quizá a través de sus colonias de Occidente.", "El infinitivo atemático en -μειν, formado sobre -μεν por analogía con -ειν, es el rasgo más característico del rodio y se documenta en Rodas, en Cárpatos y en Telos, en Fasélide y en las colonias sicilianas de Gela y Acragante, como el rodio εἴμειν o ἥμειν, que corresponde al ático εἶναι. Es también frecuente en el rodio, como en otros dialectos dóricos de las islas, la sinicesis de εο en ευ, que en las inscripciones de Rodas se documenta sobre todo desde el s. III a.C. (cap. 4, §4.1.2.3).", "La primera consulta es I.Dodone Lhôte 89Aa (s. IV a.C.), uno de los textos de un palimpsesto publicado por Carapanos que Lhôte examinó en autopsia en 1998:", "Τύχα ἀγαθά. Ἦ τυγχάνοιμί κα ἐμπορευόμενος ὅπυς κα δοκῆι σύμφορον ἔμειν καὶ ἄγων τῆι (?) κα δοκῆι ἅμα τᾶι τέχναι χρεύμενος.", "Lhôte (2006: 186-188) la atribuyó a un artesano y comerciante de lengua rodia, procedente con toda probabilidad de una colonia de Sicilia como Gela o Acragante, por tres rasgos: el infinitivo ἔμειν, que pone en relación con el rodio εἴμειν, el adverbio ὅπυς y el participio χρεύμενος, con la sinicesis εο > ευ. Giannakis (2024b: 126-127) acepta la atribución. Ninguno de los dos últimos rasgos es, sin embargo, exclusivo del rodio. El adverbio ὅπυς es dórico en general, y la grafía ευ por εο se lee también en el χρευμένα de I.Dodone DVC 3174A (primera mitad del s. V a.C.), en un alfabeto que los editores atribuyen a la Magna Grecia o a Sicilia, y en el ὠνεύμενοι de 2593A (primera mitad del s. IV a.C.), del dórico general. La atribución depende, por tanto, de ἔμειν, cuya interpretación ha discutido Méndez Dosuna (2007b: 143): un infinitivo con épsilon breve inicial es poco verosímil, el único paralelo, el cretense ἔμην de Gortina, es una forma aislada que se explica como una falta gráfica, y la desinencia -μειν solo aparece en Dodona en el decreto copiado de un modelo acragantino. El autor propone leer un infinitivo ἔ<ι>με{ι}ν, es decir, εἶμεν, o el dativo tónico del pronombre de primera persona ἐμ{ε}ίν, rasgo bien conocido del dórico, y considera sospechoso, como ya había advertido Lhôte, el adverbio τῆι, que en dórico no llevaría iota adscrita. Con ἔμειν leído como una errata, el texto es dórico, pero no por fuerza rodio, y la adscripción se califica como dudosa.", "La segunda es I.Dodone DVC 172A (finales del s. V a.C.), una consulta colectiva sobre el recurso a un psicagogo:", "[οἱ δεῖνες ἐπικοινῶνται τῶι Διὶ] τῶι Νάωι καὶ τᾶι Διώναι ἦ μὴ χρῆυνται Δωρίωι τῶ[ι] ψυχαγωγῶι;", "La forma χρῆυνται, subjuntivo deliberativo de χράομαι, tiene paralelos en dos participios del corpus, ἐποικοδομῆυν de I.Dodone Lhôte 118B (s. IV a.C.) y ν[α]<υ>κλαρη[ῦ]ν̣ de I.Dodone Lhôte 93 (ss. IV-III a.C.), y fuera de él solo en los nominativos Τιμοκρηῦν y Ἑρμοκρηῦν de Telos, una isla del ámbito rodio. Las explicaciones que se han dado de esas grafías se examinan en el dórico general (cap. 4, §4.1.2.3), donde se cuenta I.Dodone Lhôte 118B. Para la forma de I.Dodone DVC 172A, que Lhôte (2006: 391-392) atribuía con dudas a un epirota, Striano (2017: 144-153) ha propuesto un origen rodio, mientras que Alonso Déniz (2017: 134-137) la explica como una remodelación analógica del subjuntivo en un dialecto con indicativo χρεῦνται, sobre el modelo de φέρονται : φέρωνται, pero advierte que esa analogía no se documenta en Rodas ni en las islas vecinas, cuyos subjuntivos conservan -έωντι y -έωνται, y que, a falta de paralelos, es más prudente corregir χρή<ω>νται. Méndez Dosuna (2018b: 42) considera, por su parte, que la grafía ηυ por εω es difícil de explicar. En CIOD, donde la consulta se fecha hacia el 375-350 a.C., se relaciona con I.Dodone DVC 338A y 341B (principios del s. IV a.C.), que mencionan al mismo Dorio y que quizá pertenecen a los mismos consultantes, y con 3169 (principios del s. IV a.C.), por el estilo de la escritura; ninguna de ellas conserva un rasgo rodio. El rodio de I.Dodone DVC 172A descansaría, por tanto, en una forma aislada, de lectura segura pero de explicación discutida, cuyo único paralelo exacto procede de Telos, y el resto del texto solo presenta la ᾱ de τᾶι Διώναι, común a todo el dórico. Por esa razón, la consulta no se cuenta entre las rodias, sino entre las no jónico-áticas, con la calificación de dudosa, que refleja que el origen rodio sigue siendo una posibilidad. Si la propuesta de Striano es correcta, χρῆυνται sería una moda gráfica del rodio, surgida en los antropónimos en -κρέων, que se escribían también -κρων o -κρηυν, y extendida después a otras formaciones, y la consulta sería la de un grupo de rodios, o de colonos rodios de Sicilia, que preguntaban al oráculo si debían recurrir a un psicagogo. Los paralelos de I.Dodone Lhôte 118B y 93, con la misma grafía en textos dóricos que nada relaciona con Rodas, aconsejan, con todo, no atribuirla a un dialecto concreto mientras no se aclare el origen de la grafía."]}, {"sec": "§5.2", "name": "Las inscripciones no griegas", "paras": ["Dos inscripciones del corpus no pueden leerse como griego tal como están escritas. La primera se cuenta en este capítulo sin excluirla del recuento, porque documenta a un consultante y porque su condición de texto no griego es, en sí misma, un dato sobre la clientela del oráculo. Se trata de I.Dodone DVC 27A (principios del s. V a.C.), de la que la edición de 2013 solo recoge la mitad derecha, [- - -] αἰ συνναίεν ΤΑΑΡ[- - -], atribuida a un alfabeto eleo o tesalio. Evangelidis la había publicado completa en 1935, con un facsímil en el que Lhôte lee ΤΥΓΥΜΕΝΑΙΣΥΝΝΑΙΕΝΓΑΑΡΕΝ, y Lhôte (2006: 319-322), que estudia el texto a partir de ese facsímil, observa que, salvo la secuencia ΝΑΙΕ, que podría relacionarse con la epíclesis de Zeus Naios, parece escrito en una lengua no griega; en CIOD se añade que αἰ seguido de un infinitivo no tiene sentido y que a esa fecha no cabe esperar la notación de la geminada en συνναίεν. Su propuesta es que la secuencia ΓΑΑΡΕΝ corresponde a la palabra gaares de la estela de Novilara, el único texto extenso de la lengua llamada norpicena, y que el consultante, que escribe en el alfabeto local de Dodona, sería un ilirio que hablaba una lengua emparentada con ella o un esclavo o marinero originario del Piceno septentrional. En CIOD, donde la inscripción se fecha hacia el 450 a.C., se recuerda que algunos estudios recientes consideran falsas todas las estelas norpicenas, incluida la de Novilara, y se objeta que la coincidencia con la laminilla apenas puede deberse al azar. La adscripción se califica como segura en el único sentido en que puede serlo: la secuencia no es griega, cualquiera que sea la lengua en que está escrita.", "La segunda, I.Dodone DVC 3977A (segunda mitad del s. IV a.C.), consta de una sola palabra, que la laminilla escribe ΑΠΟΡΕΙΤΑΝ y que los editores corrigen en Ἀπ<ει>ρ<ο̄>τᾶ̣ν, el genitivo plural de Ἀπειρῶται, “los epirotas”. Si la corrección es acertada, se trataría de la etiqueta de una consulta pública de los epirotas, como se ha sugerido, y el texto sería griego, con la ᾱ dórica del genitivo plural. El étnico Ἀπειρῶται, de carácter supranacional, designaba a los miembros de la συμμαχία de los epirotas, documentada desde finales del s. IV a.C., lo que encaja con la fecha de la laminilla. La corrección supone, sin embargo, que el autor invirtió el orden de las vocales, ΑΠΟΡΕΙΤΑΝ por ΑΠΕΙΡΟΤΑΝ, y la secuencia, tal como está escrita, no es griega, aunque una sola palabra tampoco permite afirmar que pertenezca a otra lengua. Por eso queda sin clasificar: contarla como griega exigiría aceptar la corrección, y contarla como no griega, descartar una errata que explica bien la secuencia.", "Fuera de estas dos inscripciones, la presencia de hablantes de otras lenguas en el santuario se refleja en la onomástica. Tselikas (2018: 256) reúne una serie de nombres ilirios, como Γέντις en I.Dodone DVC 2483 (finales del s. IV a.C.), Ὄπελλος en 158B (finales del s. VI a.C.), Ἐπιδύνα en 2144B (principios del s. V a.C.), Πλαυράτα en 2609A (segunda mitad del s. IV a.C.) o [Ἐπί]καδος y Ἐτούτα en 2979 (segunda mitad del s. IV a.C.), y considera que sus portadores eran, con toda probabilidad, ilirios helenizados. La esclava Τάτα de I.Dodone DVC 3550B (primera mitad del s. V a.C.), cuyo hijo es objeto de la consulta, y el Τευτίκου de I.Dodone DVC 73, un nombre ilirio deformado, según CIOD, en ΤΕΙΤΥΚΟ, en una consulta relacionada con la παραμονή, muestran que esos consultantes eran a menudo esclavos o libertos que vivían en el entorno del santuario. Todos ellos escribieron en griego, aunque a veces con dificultad, y solo en I.Dodone DVC 27A, y quizá en 3977A, el texto mismo parece ajeno a la lengua."]}, {"sec": "§5.3", "name": "Otras variedades", "paras": ["La distribución de la tesis prevé, entre los testimonios minoritarios, el corintio, el corcireo y el jónico oriental, que por el número de sus inscripciones o por los criterios de adscripción se estudian en otros capítulos. Las consultas de Corinto y de sus colonias, Corcira incluida, conservan el vocalismo de la Doris mitior y se cuentan en el dórico general, en el que se examinan su alfabeto y las consultas públicas de los corcirenses (cap. 4, §2-§3). Las consultas en jónico oriental, reconocibles por εἰρωτᾶι, con el tercer alargamiento compensatorio, como I.Dodone DVC 1881A (principios del s. IV a.C.) e I.Dodone Lhôte 100A (primer cuarto del s. IV a.C.), se estudian en el jónico (cap. 10), y las que combinan ese rasgo con formas dóricas, como la de Porino de Cime en I.Dodone DVC 35A (segunda mitad del s. IV a.C.) o 1014B (principios del s. IV a.C.), en la mezcla dialectal (cap. 13). También el eubeo, que es un dialecto jónico, se estudia en el capítulo del jónico (cap. 10, §2 y §4.6), donde se examinan las tradiciones que vinculaban Eubea con Dodona y, como un caso especial, la única consulta que conserva un rasgo propio de una de sus variedades: la del eretrio Ὀνήριμος, I.Dodone DVC 2217A (segunda mitad del s. IV a.C.), cuyo carácter jónico-ático asegura el artículo τὴν̣ y cuyo eretrio descansa en el antropónimo.", "Tampoco hay un dialecto epirota que pueda separarse del dórico del Noroeste. Lhôte (2006: 430-431) concluyó que no es posible aislar un solo rasgo gramatical que oponga las inscripciones epirotas a los dialectos dóricos conocidos, y las consultas de los epirotas se estudian en el capítulo del dórico noroccidental (cap. 5). El iotacismo temprano que Méndez Dosuna (1985: 50) atribuye al epirota y que podría reconocerse en el ὠ̣φελῖ de I.Dodone DVC 503B (primera mitad del s. IV a.C.) no basta, en una laminilla sin otro rasgo visible, para ninguna adscripción."]}, {"sec": "§6", "name": "Los dialectos minoritarios y la historia del santuario", "paras": ["Las doce inscripciones de este capítulo representan el 0,8 % del corpus con características dialectales, y una lectura estricta de los indicios ha reducido ya su número. Ninguna de las consultas atribuidas a la Élide conserva un rasgo exclusivo de este dialecto. De las seis que los editores asignan al alfabeto de la Élide, cinco se cuentan entre las no jónico-áticas, porque el alfabeto no está bien identificado y sus rasgos son comunes a todos los dialectos distintos del jónico-ático, y la sexta, I.Dodone DVC 1993A, en el dórico general, porque sus rasgos contradicen el eleo; de las dos que se mantienen en el grupo, [Ἱ]πόζαμο<ς>, en alfabeto aqueo, puede pertenecer a un consultante de la frontera entre Acaya y la Élide, y μαστείε̄ι admite una explicación dórica. El rodio de I.Dodone Lhôte 89Aa depende de una forma cuya lectura se discute, y el de I.Dodone DVC 172A, de una grafía que no se documenta en Rodas, por lo que esta última se cuenta entre las no jónico-áticas; el macedonio descansa, sobre todo, en los nombres de los consultantes, mientras que el eretrio de I.Dodone DVC 2217A, que se estudia en el jónico, se reconoce por el nombre en un texto jónico-ático seguro. Los testimonios más sólidos son el nombre Κεβάλιος, la secuencia no griega de I.Dodone DVC 27A y las cinco consultas aqueas con un rasgo no jónico-ático visible; la sexta, I.Dodone DVC 109A, solo se reconoce por el alfabeto, que mezcla con la Η jónica.", "La cifra, con todo, mide la visibilidad de estos dialectos más que su presencia. Dos factores, uno gráfico y otro lingüístico, la limitan. Hasta finales del s. V a.C., los alfabetos epicóricos permiten reconocer a los consultantes que escribían en la escritura de su ciudad, y por eso las consultas aqueas y las atribuidas a la Élide se concentran en los ss. VI y V a.C., aunque la semejanza entre los alfabetos “rojos” limita esa vía incluso entonces; con la difusión del alfabeto jónico, esa vía desaparece, y un aqueo o un eleo que no conservara un rasgo propio pasa a contarse entre las no jónico-áticas o entre las dóricas. Los dialectos de este capítulo, además, comparten con el dórico del entorno la mayoría de los rasgos que aparecen en las consultas, la ᾱ, κα, αἰ, las contracciones de la fórmula, de modo que sus rasgos propios, cuando existen, son raros o tardíos, como la σ por θ del laconio o el rotacismo eleo. En el s. IV a.C., por ello, solo los antropónimos y alguna forma aislada delatan a estos consultantes, y los macedonios que escribían en koiné resultan del todo invisibles. Como en la Doris severior, el número de inscripciones debe entenderse como un límite inferior.", "Lo que estas consultas permiten ver de la historia del santuario confirma, en lo esencial, el mapa de Lhôte, pero lo matiza en varios puntos. El grueso de los testimonios dibuja la red marítima del Occidente: las colonias aqueas de la Magna Grecia, con consultas desde finales del s. VI a.C., las colonias rodias de Sicilia, cuya relación con los molosos documenta el decreto de proxenia para los acragantinos, aunque ninguna consulta pueda atribuirse con seguridad a un rodio, y, si se acepta la propuesta de CIOD sobre el eretrio de I.Dodone DVC 2217A, una colonia eubea de Italia. Son las mismas rutas que reflejan las menciones de Crotona y de Metaponto y las consultas de la Magna Grecia en Doris severior (cap. 6), y confirman que el santuario atraía a los griegos de Occidente a través del mar Jónico, de Corcira y de Ambracia. Hacia el este, Macedonia solo aparece en la primera mitad del s. IV a.C., cuando el reino moloso entraba en su órbita, y lo hace a través de dos nombres, mientras que la influencia macedonia de la segunda mitad del s. IV a.C. se manifiesta en el contenido de las consultas y en las ofrendas, no en el dialecto. El Peloponeso, por último, mantiene la posición marginal que le atribuía Lhôte: la Élide, pese a la vecindad religiosa de Olimpia, no deja ningún texto eleo inequívoco, y los colonos eleos que la tradición sitúa en la Casopia, si existían ya en el s. V a.C., solo serían reconocibles por su alfabeto, porque escribían en el dórico de su entorno (§4.1.3). Esparta, cuya devoción por Dodona documentan los bronces del s. VI a.C. y las fuentes literarias, solo aparece en nombres y topónimos. Las consultas de Estado que transmiten esas fuentes no son las que conservan las laminillas, que reflejan la piedad privada.", "La relación entre el número de inscripciones y la importancia histórica de cada región es, por tanto, inversa en más de un caso. Las regiones con vínculos políticos o religiosos más estrechos con el santuario, como Macedonia, la Élide o Esparta, son las que menos huella dialectal dejan, mientras que los consultantes aqueos de la Magna Grecia, que no ocupan ningún lugar en las fuentes literarias sobre Dodona, son los más fáciles de reconocer, gracias a su alfabeto. Las inscripciones no griegas y la onomástica iliria añaden, por su parte, un componente que las fuentes apenas mencionan: la presencia en el santuario de esclavos y de extranjeros que, sin dominar el griego, recurrían también al oráculo. Buena parte de los consultantes de estas regiones debe de esconderse, en suma, entre las inscripciones no jónico-áticas, que no permiten precisar el dialecto y que se estudian en el capítulo siguiente."]}];

